// ==========================================================================
// Design Tokens - Figma「Nusk」デザインから抽出
// ==========================================================================

// --- Color Palette ---
$colors: (
  'primary':        #f97316,
  'primary-light':  #fff7ed,

  'text':           #111111,
  'text-secondary': #999999,
  'text-muted':     #9ca3af,
  'text-gray':      #6b7280,
  'text-calendar':  #4b5563,
  'text-disabled':  #d1d5db,

  'bg':             #f5f5f5,
  'surface':        #ffffff,
  'surface-muted':  #f9fafb,

  'border':         #e5e7eb,
  'border-light':   #f3f4f6,
  'border-danger':  #fecaca,

  'status-blue':    #2563eb,
  'status-blue-bg': #eff6ff,
  'status-green':   #059669,
  'status-green-bg':#ecfdf5,

  'danger':         #dc2626,
  'danger-bg':      #fef2f2,
);

// --- Spacing Scale (4px base) ---
$spacing: (
  1:  4px,
  2:  8px,
  3:  12px,
  4:  16px,
  5:  20px,
  6:  24px,
  8:  32px,
  10: 40px,
  12: 48px,
);

// --- Font Family ---
$font-family-base: 'Noto Sans JP', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
$font-family-logo: 'Inter', sans-serif;

// --- Font Size ---
$font-sizes: (
  'xs':      10px,
  'sm':      11px,
  'base-sm': 12px,
  'base':    14px,
  'md':      16px,
  'lg':      24px,
  'xl':      32px,
);

// --- Font Weight ---
$font-weights: (
  'regular': 400,
  'medium':  500,
  'bold':    700,
);

// --- Border Radius ---
$radii: (
  'sm':   4px,
  'md':   8px,
  'lg':   12px,
  'pill': 9999px,
);

// --- Box Shadow ---
$shadows: (
  'card':     (0 1px 4px rgba(0, 0, 0, 0.04)),
  'card-hover':(0 2px 8px rgba(0, 0, 0, 0.08)),
  'elevated': (0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.05)),
  'button':   (0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1)),
  'subtle':   (0 1px 2px 0 rgba(0, 0, 0, 0.05)),
  'input':    (0 2px 16px rgba(0, 0, 0, 0.08)),
);

// --- Layout ---
$sidebar-width: 260px;

// --- Transition ---
$transition-fast: 0.15s ease;

// ==========================================================================
// Helper Functions - マップからトークン値を取得するショートハンド
// ==========================================================================

@use 'variables' as *;

@function color($key) {
  $value: map-get($colors, $key);
  @if $value == null {
    @error 'Unknown color token: `#{$key}`. Available: #{map-keys($colors)}';
  }
  @return $value;
}

@function spacing($key) {
  $value: map-get($spacing, $key);
  @if $value == null {
    @error 'Unknown spacing token: `#{$key}`. Available: #{map-keys($spacing)}';
  }
  @return $value;
}

@function font-size($key) {
  $value: map-get($font-sizes, $key);
  @if $value == null {
    @error 'Unknown font-size token: `#{$key}`. Available: #{map-keys($font-sizes)}';
  }
  @return $value;
}

@function font-weight($key) {
  $value: map-get($font-weights, $key);
  @if $value == null {
    @error 'Unknown font-weight token: `#{$key}`. Available: #{map-keys($font-weights)}';
  }
  @return $value;
}

@function radius($key) {
  $value: map-get($radii, $key);
  @if $value == null {
    @error 'Unknown radius token: `#{$key}`. Available: #{map-keys($radii)}';
  }
  @return $value;
}

@function shadow($key) {
  $value: map-get($shadows, $key);
  @if $value == null {
    @error 'Unknown shadow token: `#{$key}`. Available: #{map-keys($shadows)}';
  }
  @return $value;
}

// ==========================================================================
// Mixins - Figmaデザインから抽出した共通パターン
// ==========================================================================

@use 'variables' as *;
@use 'functions' as *;

// --- Typography ---
@mixin typography($size: 'base', $weight: 'regular') {
  font-family: $font-family-base;
  font-size: font-size($size);
  font-weight: font-weight($weight);
}

// --- Text Truncation ---
@mixin truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

// --- Card ---
@mixin card($r: 'md') {
  background: color('surface');
  border: 1px solid color('border-light');
  border-radius: radius($r);
}

// --- Button Base ---
@mixin btn-base {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: spacing(2);
  border: none;
  border-radius: radius('md');
  font-family: $font-family-base;
  font-weight: font-weight('medium');
  cursor: pointer;
  transition: background $transition-fast, box-shadow $transition-fast;

  &:disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }
}

// --- Primary Button ---
@mixin btn-primary {
  @include btn-base;
  background: color('primary');
  color: color('surface');
  box-shadow: shadow('button');

  &:hover:not(:disabled) {
    filter: brightness(1.05);
  }
}

// --- Secondary Button (outlined) ---
@mixin btn-secondary {
  @include btn-base;
  background: color('surface');
  color: color('text');
  border: 1px solid color('border');

  &:hover:not(:disabled) {
    background: color('bg');
  }
}

// --- Ghost Button (borderless) ---
@mixin btn-ghost {
  @include btn-base;
  background: transparent;
  color: color('text-secondary');

  &:hover:not(:disabled) {
    background: color('bg');
  }
}

// --- Status Badge ---
@mixin status-badge($bg-color, $text-color) {
  display: inline-block;
  padding: 2px spacing(2);
  border-radius: radius('sm');
  font-size: font-size('xs');
  font-weight: font-weight('bold');
  text-transform: uppercase;
  line-height: 15px;
  white-space: nowrap;
  background: $bg-color;
  color: $text-color;
}

// --- Section Label (サイドバーの「リスト」「日付」等) ---
@mixin section-label {
  font-size: font-size('sm');
  font-weight: font-weight('bold');
  color: color('text-muted');
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

// --- Flex Center ---
@mixin flex-center {
  display: flex;
  align-items: center;
  justify-content: center;
}

// --- Flex Between ---
@mixin flex-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

// ==========================================================================
// Global Styles - リセット + ベーススタイル
// ==========================================================================

@use 'variables' as *;
@use 'functions' as *;

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  font-family: $font-family-base;
  font-size: font-size('base');
  font-weight: font-weight('regular');
  color: color('text');
  background: color('bg');
  line-height: 1.5;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
}

img {
  display: block;
  max-width: 100%;
}

ul,
ol {
  list-style: none;
}

