@function color($key) {
  // 1. セマンティック層を確認 → パレットキーに解決
  $resolved: map.get($semantic-colors, $key);
  @if $resolved != null {
    $key: $resolved;
  }

  // 2. パレット層から値を取得
  $value: map.get($palette, $key);
  @if $value == null {
    @error 'Unknown color token: `#{$key}`. Available palette: #{map.keys($palette)}, semantic: #{map.keys($semantic-colors)}';
  }
  @return $value;
}

